import axios from 'axios';

const instance = axios.create({
  baseURL: 'http://localhost:4000/api',
  withCredentials: true
});

instance.interceptors.response.use(
  res => res,
  async err => {
    const original = err.config;

    // если нет ответа или запрос уже повторяли → сразу отклоняем
    if (!err.response || original._retry) {
      return Promise.reject(err);
    }

    // если access_token истёк → пробуем обновить
    if (err.response.status === 401) {
      original._retry = true;
      try {
        await instance.post('/auth/refresh');
        return instance(original); // повторяем исходный запрос
      } catch (refreshErr) {
        // если refresh тоже 401 → выходим на /login
        if (refreshErr.response?.status === 401) {
          window.location.href = '/login';
        }
        return Promise.reject(refreshErr);
      }
    }

    return Promise.reject(err);
  }
);

export default instance;
